package com.library.controller;
import com.library.model.IssueRecord; import com.library.util.DBConnection; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import java.util.*; import java.math.BigDecimal;
@WebServlet("/returns") public class ReturnsServlet extends HttpServlet {
 private List<IssueRecord> load(String status)throws SQLException{List<IssueRecord> list=new ArrayList<>();String q="SELECT i.id,b.title,m.name,i.issue_date,i.due_date,i.return_date,i.fine,i.status FROM issued_books i JOIN books b ON b.id=i.book_id JOIN members m ON m.id=i.member_id WHERE i.status=? ORDER BY i.id DESC";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,status);try(ResultSet r=p.executeQuery()){while(r.next())list.add(new IssueRecord(r.getInt(1),r.getString(2),r.getString(3),r.getDate(4).toLocalDate(),r.getDate(5).toLocalDate(),r.getDate(6)==null?null:r.getDate(6).toLocalDate(),r.getBigDecimal(7)==null?BigDecimal.ZERO:r.getBigDecimal(7),r.getString(8)));}}return list;}
 protected void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{try{req.setAttribute("activeIssues",load("ISSUED"));req.setAttribute("returnedIssues",load("RETURNED"));if("issued".equals(req.getParameter("ok")))req.setAttribute("message","Book issued successfully.");if("returned".equals(req.getParameter("ok")))req.setAttribute("message","Book returned successfully.");if(req.getParameter("error")!=null)req.setAttribute("error",req.getParameter("error"));req.getRequestDispatcher("/returns.jsp").forward(req,res);}catch(Exception e){throw new ServletException(e);}}
}
